const DAY_MS = 24 * 60 * 60 * 1000;
const HOUR_MS = 60 * 60 * 1000;
const now = new Date();

function validDate(value) {
  if (!value) return null;

  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

return $input.all().map((item) => {
  const application = item.json;

  const vacancy = application.vacancies || {};
  const client = vacancy.clients || {};
  const candidate = application.candidates || {};
  const interviews = application.interviews || [];
  const tasks = application.tasks || [];
  const activities = application.activities || [];

  // Estimate the recruitment agency's placement fee.
  const salary =
    Number(vacancy.salary_max) ||
    Number(vacancy.salary_min) ||
    0;

  const feePercentage =
    Number(client.placement_fee_percentage) ||
    0;

  const estimatedPlacementValue = Math.round(
    salary * (feePercentage / 100)
  );

  // Calculate how long the application has been inactive.
  const lastActivityDate = validDate(application.last_activity_at);

  const daysInactive = lastActivityDate
    ? Math.max(
        0,
        Math.floor((now - lastActivityDate) / DAY_MS)
      )
    : null;

  // Find incomplete and overdue tasks.
  const openTasks = tasks.filter(
    (task) => !["completed", "cancelled"].includes(task.status)
  );

  const overdueTasks = openTasks.filter((task) => {
    const dueDate = validDate(task.due_at);
    return dueDate && dueDate < now;
  });

  // Find the next upcoming interview.
  const upcomingInterviews = interviews
    .map((interview) => ({
      ...interview,
      calculatedDate: validDate(
        interview.scheduled_at ||
        interview.interview_at ||
        interview.start_time
      ),
    }))
    .filter(
      (interview) =>
        interview.calculatedDate &&
        interview.calculatedDate >= now &&
        interview.status !== "cancelled"
    )
    .sort(
      (a, b) =>
        a.calculatedDate.getTime() -
        b.calculatedDate.getTime()
    );

  const nextInterview = upcomingInterviews[0] || null;

  const hoursUntilNextInterview = nextInterview
    ? Math.round(
        (nextInterview.calculatedDate - now) / HOUR_MS
      )
    : null;

  // Check whether a reminder has already been recorded.
  const reminderActivityFound = activities.some((activity) =>
    String(activity.activity_type || "")
      .toLowerCase()
      .includes("reminder")
  );

  return {
    json: {
      ...application,

      pipeline_metrics: {
        calculated_at: now.toISOString(),

        client_name: client.name || null,
        vacancy_title: vacancy.title || null,
        candidate_name: candidate.name || null,

        salary_used: salary,
        placement_fee_percentage: feePercentage,
        estimated_placement_value: estimatedPlacementValue,

        days_inactive: daysInactive,

        open_task_count: openTasks.length,
        overdue_task_count: overdueTasks.length,
        has_overdue_task: overdueTasks.length > 0,

        next_interview_at: nextInterview
          ? nextInterview.calculatedDate.toISOString()
          : null,

        hours_until_next_interview: hoursUntilNextInterview,
        reminder_activity_found: reminderActivityFound,
      },
    },
  };
});

