const recommendations = $input.first().json.recommendations ?? [];

const totalRevenueAtRisk = recommendations.reduce(
  (sum, item) => sum + Number(item.revenue_at_risk || 0),
  0
);

const highPriorityCount = recommendations.filter(
  item => item.priority === 'high'
).length;

const riskBreakdown = recommendations.reduce((breakdown, item) => {
  const risk = item.recommendation_type || 'other';
  breakdown[risk] = (breakdown[risk] || 0) + 1;
  return breakdown;
}, {});

const breakdownText = Object.entries(riskBreakdown)
  .map(([risk, count]) => {
    return `• ${risk.replaceAll('_', ' ')}: ${count}`;
  })
  .join('\n');

const actionText = recommendations
  .map((item, index) => {
    const revenue = Number(item.revenue_at_risk || 0).toLocaleString('en-US');

    return `${index + 1}. ${item.title}
Revenue at risk: ${item.currency || 'USD'} ${revenue}
Action: ${item.recommended_action}`;
  })
  .join('\n\n');

const generatedAt = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Africa/Lagos',
  dateStyle: 'medium',
  timeStyle: 'short'
}).format(new Date());

const summaryMessage = `📊 RECRUITMENT RECOVERY SUMMARY

Generated: ${generatedAt}
Risks detected: ${recommendations.length}
High-priority risks: ${highPriorityCount}
Total revenue at risk: USD ${totalRevenueAtRisk.toLocaleString('en-US')}

Risk breakdown:
${breakdownText}

Required actions:
${actionText}`;

return [
  {
    json: {
      generated_at: generatedAt,
      recommendations_count: recommendations.length,
      high_priority_count: highPriorityCount,
      total_revenue_at_risk: totalRevenueAtRisk,
      currency: 'USD',
      risk_breakdown: riskBreakdown,
      summary_message: summaryMessage
    }
  }
];
